export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const tEnd = (2 * u) / g;
  const tClamped = Math.min(Math.max(0, time), tEnd);

  const v = u - g * tClamped;
  const y = u * tClamped - 0.5 * g * tClamped * tClamped;
  const a = -g;
  const Fg = m * g;

  let motionState = "Ready to toss";
  if (tClamped === 0) {
    motionState = "Ready to toss";
  } else if (Math.abs(tClamped - tTop) < 0.015) {
    motionState = "At the top";
  } else if (tClamped < tTop) {
    motionState = "Rising";
  } else if (tClamped < tEnd) {
    motionState = "Falling";
  } else {
    motionState = "Back at launch height";
  }

  const leftPanel = sdk.panel({
    id: "lane.motion",
    x: 20,
    y: 30,
    w: 280,
    h: 360,
    title: "The motion",
    state: motionState
  });

  const axisH = 280;
  const axisX = 90;
  const axisY = 370;
  const yRuler = sdk.axis("axis.y", {
    x: axisX,
    y: axisY,
    length: axisH,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const ballPxY = axisY - (y / 2.2) * axisH;
  const ballPxX = axisX + 40;

  const ballObj = sdk.circle("ball.toss", ballPxX, ballPxY, 24);

  const vecV = sdk.vector("vec.v", { x: ballPxX, y: ballPxY }, {
    value: v,
    direction: "up",
    scale: 15,
    label: "v"
  });

  const vecA = sdk.vector("vec.a", { x: ballPxX + 30, y: ballPxY }, {
    value: a,
    direction: "up",
    scale: 8,
    label: "a"
  });

  const calloutLines = [
    `v = ${v.toFixed(2)} m/s`,
    `a = ${a.toFixed(1)} m/s²`,
    `Fg = ${Fg.toFixed(1)} N`
  ];
  const calloutObj = sdk.callout(ballPxX + 50, ballPxY - 20, calloutLines, { id: "callout.toss" });

  const rightPanel = sdk.panel({
    id: "lane.vt",
    x: 320,
    y: 30,
    w: 300,
    h: 360,
    title: "Velocity over time",
    state: `t = ${tClamped.toFixed(2)} s`
  });

  const numPoints = 21;
  const pts = [];
  for (let i = 0; i <= numPoints; i++) {
    const tp = (tEnd * i) / numPoints;
    const vp = u - g * tp;
    pts.push({ x: tp, y: vp });
  }

  const plotObj = sdk.plot("plot.vt", {
    x: 340,
    y: 80,
    w: 260,
    h: 280,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: pts
      }
    ]
  });

  const objects = [
    ...leftPanel,
    yRuler,
    ballObj,
    ...vecV,
    ...vecA,
    ...calloutObj,
    ...rightPanel,
    plotObj
  ];

  const readouts = [
    { id: "velocity", value: v },
    { id: "acceleration", value: a },
    { id: "force", value: Fg },
    { id: "motionState", value: motionState }
  ];

  const quantities = {
    launchSpeed: u,
    gravity: g,
    mass: m,
    apexTime: tTop,
    apexHeight: (u * u) / (2 * g),
    height: y,
    velocity: v,
    acceleration: a,
    force: Fg
  };

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts
    },
    quantities
  };
}
